INSERT [dbo].[DeviceScripts] ([Script_GUID], [Script_Description_short], [Script_Description_long], [Script_Code], [Script_WorksOnComputerTypes], [Script_WhenCreated], [Script_UserCreated], [ScriptOutputType], [ScriptEnabled]) VALUES (N'9fcec0a7-01fd-4e10-a5f6-a504263c167f', N'BrowserExt', N'', N'<#
.SYNOPSIS
    Hoofdscript voor het verzamelen van browser extensies.
.DESCRIPTION
    Dit script bevat subfuncties voor Chrome, Edge en Firefox.
    Het verzamelt generiek de geïnstalleerde extensies, filtert optioneel systeem-componenten en propageert fouten naar de hoofdlus.
.VERSION
    1.6 (Final met Error Propagation)
#>

function Get-ChromeExtensions {
    <#
    .SYNOPSIS
        Leest geïnstalleerde Google Chrome extensies uit en lost gelokaliseerde namen/beschrijvingen op.
    .DESCRIPTION
        Zoekt naar manifest.json bestanden en leest indien nodig de _locales map uit. 
    .VERSION
        1.6
    #>
    [CmdletBinding()]
    param(
        [string]$BasePath = "$env:LOCALAPPDATA\Google\Chrome\User Data",
        [switch]$ExcludeSystem
    )
    
    try {
        [array]$ExtList = @()
        [array]$SystemIDs = @(
            ''ghbmnnjooekpmoecnnnilnnbdlolhkhi'', # Offline Documenten
            ''nmmhkkegccagdldgiimedpiccmgmieda'', # Betalingen via Chrome Web Store
            ''apdfllckaahabafndbhieahigkjlhalf'', # Google Drive
            ''aohghmighlieiainnegkcijnfilokake'', # Google Docs
            ''felcaaldnbdncclmgdcncolpebgiejcg'', # Google Sheets
            ''pjkljhegncpnkpknbcohdijeoejaedia''  # Gmail
        )

        Write-Debug "Start Get-ChromeExtensions. Zoeken in pad = $BasePath"
        
        if (Test-Path -Path $BasePath) {
            [array]$ManifestFiles = Get-ChildItem -Path $BasePath -Filter "manifest.json" -Recurse -Depth 5 -ErrorAction SilentlyContinue | Where-Object { $_.FullName -match "\\Extensions\\" }

            foreach ($File in $ManifestFiles) {
                [string]$ExtID = $File.Directory.Parent.Name

                if ($ExcludeSystem -and ($SystemIDs -contains $ExtID)) {
                    Write-Debug "Systeem extensie overgeslagen (Chrome). ID = $ExtID"
                    continue
                }

                $JsonContent = Get-Content -Path $File.FullName -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop
                
                [string]$ProfileName = ($File.FullName -split "\\User Data\\")[1].Split("\\")[0]

                [string]$ExtName = if ($JsonContent.name) { $JsonContent.name } else { ''Onbekend'' }
                [string]$ExtDesc = if ($JsonContent.description) { $JsonContent.description } else { ''Geen beschrijving'' }

                if ($ExtName -match "__MSG_(.*?)__") {
                    [string]$MsgKeyName = $Matches[1]
                    $ExtName = Get-LocalizedText -ManifestDir $File.DirectoryName -MsgKey $MsgKeyName -Fallback $ExtName
                }

                if ($ExtDesc -match "__MSG_(.*?)__") {
                    [string]$MsgKeyDesc = $Matches[1]
                    $ExtDesc = Get-LocalizedText -ManifestDir $File.DirectoryName -MsgKey $MsgKeyDesc -Fallback $ExtDesc
                }

                [PSCustomObject]$ExtObj = [PSCustomObject]@{
                    Browser      = ''Google Chrome''
                    Profile      = $ProfileName
                    ExtensionID  = $ExtID
                    Name         = $ExtName
                    Version      = if ($JsonContent.version) { $JsonContent.version } else { ''Onbekend'' }
                    Author       = if ($JsonContent.author) { $JsonContent.author } elseif ($JsonContent.short_name) { $JsonContent.short_name } else { ''Onbekend'' }
                    Description  = $ExtDesc
                    Permissions  = if ($JsonContent.permissions) { $JsonContent.permissions -join '', '' } else { ''Geen'' }
                    InstallPath  = $File.DirectoryName
                }
                $ExtList += $ExtObj
            }
        } else {
            Write-Debug "Pad niet gevonden = $BasePath"
        }
        
        return [array]$ExtList

    } catch {
        # Alleen Throwen zodat de foutmelding in de hoofdLus gelogd wordt met ErrorHandler
        Throw $_
    }
}

function Get-EdgeExtensions {
    <#
    .SYNOPSIS
        Leest geïnstalleerde Microsoft Edge extensies uit en lost gelokaliseerde strings op.
    .DESCRIPTION
        Zoekt naar manifest.json bestanden en filtert in-built apps.
    .VERSION
        1.6
    #>
    [CmdletBinding()]
    param(
        [string]$BasePath = "$env:LOCALAPPDATA\Microsoft\Edge\User Data",
        [switch]$ExcludeSystem
    )
    
    try {
        [array]$ExtList = @()
        [array]$SystemIDs = @(
            ''ghbmnnjooekpmoecnnnilnnbdlolhkhi'', # Offline Documenten (vaak ook in Edge)
            ''jmjflgjpcpepeafmmgdpfkogkghcpiha''  # Edge relevant text changes
        )

        Write-Debug "Start Get-EdgeExtensions. Zoeken in pad = $BasePath"
        
        if (Test-Path -Path $BasePath) {
            [array]$ManifestFiles = Get-ChildItem -Path $BasePath -Filter "manifest.json" -Recurse -Depth 5 -ErrorAction SilentlyContinue | Where-Object { $_.FullName -match "\\Extensions\\" }

            foreach ($File in $ManifestFiles) {
                [string]$ExtID = $File.Directory.Parent.Name

                if ($ExcludeSystem -and ($SystemIDs -contains $ExtID)) {
                    Write-Debug "Systeem extensie overgeslagen (Edge). ID = $ExtID"
                    continue
                }

                $JsonContent = Get-Content -Path $File.FullName -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop
                
                [string]$ProfileName = ($File.FullName -split "\\User Data\\")[1].Split("\\")[0]
                
                [string]$ExtName = if ($JsonContent.name) { $JsonContent.name } else { ''Onbekend'' }
                [string]$ExtDesc = if ($JsonContent.description) { $JsonContent.description } else { ''Geen beschrijving'' }

                if ($ExtName -match "__MSG_(.*?)__") {
                    [string]$MsgKeyName = $Matches[1]
                    $ExtName = Get-LocalizedText -ManifestDir $File.DirectoryName -MsgKey $MsgKeyName -Fallback $ExtName
                }

                if ($ExtDesc -match "__MSG_(.*?)__") {
                    [string]$MsgKeyDesc = $Matches[1]
                    $ExtDesc = Get-LocalizedText -ManifestDir $File.DirectoryName -MsgKey $MsgKeyDesc -Fallback $ExtDesc
                }

                [PSCustomObject]$ExtObj = [PSCustomObject]@{
                    Browser      = ''Microsoft Edge''
                    Profile      = $ProfileName
                    ExtensionID  = $ExtID
                    Name         = $ExtName
                    Version      = if ($JsonContent.version) { $JsonContent.version } else { ''Onbekend'' }
                    Author       = if ($JsonContent.author) { $JsonContent.author } elseif ($JsonContent.short_name) { $JsonContent.short_name } else { ''Onbekend'' }
                    Description  = $ExtDesc
                    Permissions  = if ($JsonContent.permissions) { $JsonContent.permissions -join '', '' } else { ''Geen'' }
                    InstallPath  = $File.DirectoryName
                }
                $ExtList += $ExtObj
            }
        } else {
            Write-Debug "Pad niet gevonden = $BasePath"
        }
        
        return [array]$ExtList

    } catch {
        # Alleen Throwen zodat de foutmelding in de hoofdLus gelogd wordt met ErrorHandler
        Throw $_
    }
}

function Get-FirefoxExtensions {
    <#
    .SYNOPSIS
        Leest geïnstalleerde Mozilla Firefox extensies uit inclusief UTF8 afhandeling.
    .DESCRIPTION
        Parseert het extensions.json bestand per Firefox profiel en filtert mozilla basis-addons.
    .VERSION
        1.6
    #>
    [CmdletBinding()]
    param(
        [string]$BasePath = "$env:APPDATA\Mozilla\Firefox\Profiles",
        [switch]$ExcludeSystem
    )
    
    try {
        [array]$ExtList = @()
        Write-Debug "Start Get-FirefoxExtensions. Zoeken in pad = $BasePath"
        
        if (Test-Path -Path $BasePath) {
            [array]$JsonFiles = Get-ChildItem -Path $BasePath -Filter "extensions.json" -Recurse -Depth 2 -ErrorAction SilentlyContinue

            foreach ($File in $JsonFiles) {
                [string]$ProfileName = $File.Directory.Name
                $JsonContent = Get-Content -Path $File.FullName -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop

                foreach ($Addon in $JsonContent.addons) {
                    
                    if ($ExcludeSystem -and ($Addon.id -match ''@mozilla\.(org|com)$'')) {
                        Write-Debug "Systeem extensie overgeslagen (Firefox). ID = $($Addon.id)"
                        continue
                    }

                    [string]$ExtName = ''Onbekend''
                    if (-not [string]::IsNullOrWhiteSpace($Addon.name)) {
                        $ExtName = $Addon.name
                    } elseif ($Addon.defaultLocale.name) {
                        $ExtName = $Addon.defaultLocale.name
                    }

                    [string]$ExtDesc = ''Geen beschrijving''
                    if (-not [string]::IsNullOrWhiteSpace($Addon.description)) {
                        $ExtDesc = $Addon.description
                    } elseif ($Addon.defaultLocale.description) {
                        $ExtDesc = $Addon.defaultLocale.description
                    }

                    [PSCustomObject]$ExtObj = [PSCustomObject]@{
                        Browser      = ''Mozilla Firefox''
                        Profile      = $ProfileName
                        ExtensionID  = $Addon.id
                        Name         = $ExtName
                        Version      = if ($Addon.version) { $Addon.version } else { ''Onbekend'' }
                        Author       = if ($Addon.creator.name) { $Addon.creator.name } else { ''Onbekend'' }
                        Description  = $ExtDesc
                        Permissions  = if ($Addon.permissions) { $Addon.permissions -join '', '' } else { ''Geen'' }
                        InstallPath  = if ($Addon.sourceURI) { $Addon.sourceURI } else { $File.DirectoryName }
                    }
                    $ExtList += $ExtObj
                }
            }
        } else {
            Write-Debug "Pad niet gevonden = $BasePath"
        }
        
        return [array]$ExtList

    } catch {
        # Alleen Throwen zodat de foutmelding in de hoofdLus gelogd wordt met ErrorHandler
        Throw $_
    }
}

function Get-LocalizedText {
    <#
    .SYNOPSIS
        Helper functie om de lokalisatiesleutel op te zoeken in de _locales map.
    .VERSION
        1.2
    #>
    [CmdletBinding()]
    param(
        [string]$ManifestDir,
        [string]$MsgKey,
        [string]$Fallback
    )
    
    try {
        [string]$LocalePathEN = Join-Path -Path $ManifestDir -ChildPath "_locales\en\messages.json"
        [string]$LocalePathENUS = Join-Path -Path $ManifestDir -ChildPath "_locales\en_US\messages.json"
        [string]$LocalePathNL = Join-Path -Path $ManifestDir -ChildPath "_locales\nl\messages.json"
        
        [string]$FoundLocalePath = ''''
        if (Test-Path $LocalePathNL) { $FoundLocalePath = $LocalePathNL }
        elseif (Test-Path $LocalePathEN) { $FoundLocalePath = $LocalePathEN }
        elseif (Test-Path $LocalePathENUS) { $FoundLocalePath = $LocalePathENUS }

        if ($FoundLocalePath -ne '''') {
            $LocaleJson = Get-Content -Path $FoundLocalePath -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop
            if ($LocaleJson.$MsgKey.message) {
                return [string]$LocaleJson.$MsgKey.message
            }
        }
        
        return [string]$Fallback

    } catch {
        # Alleen Throwen zodat de foutmelding in de hoofdLus gelogd wordt met ErrorHandler
        Throw $_
    }
}

function Get-AllBrowserExtensions {
    <#
    .SYNOPSIS
        Verzamelt extensies van alle ondersteunde browsers.
    .DESCRIPTION
        Roept de specifieke subfuncties aan en retourneert een gecombineerde array. Nu met centrale Error Propagation.
    .VERSION
        1.3
    #>
    [CmdletBinding()]
    param(
        [switch]$ExcludeSystem
    )

    try {
        [array]$AllExtensions = @()

        [array]$ChromeExt = Get-ChromeExtensions -ExcludeSystem:$ExcludeSystem
        if ($ChromeExt.Count -gt 0) { $AllExtensions += $ChromeExt }

        [array]$EdgeExt = Get-EdgeExtensions -ExcludeSystem:$ExcludeSystem
        if ($EdgeExt.Count -gt 0) { $AllExtensions += $EdgeExt }

        [array]$FirefoxExt = Get-FirefoxExtensions -ExcludeSystem:$ExcludeSystem
        if ($FirefoxExt.Count -gt 0) { $AllExtensions += $FirefoxExt }

        return [array]$AllExtensions

    } catch {
        # Alleen Throwen zodat de foutmelding in de hoofdLus gelogd wordt met ErrorHandler
        Throw $_
    }
}

# --- Uitvoering van het script in de HoofdLus ---
# Als je dit aanroept vanuit een groter script met een eigen try/catch, 
# zal de globale catch het originele $_ object netjes opvangen.
try {
    [array]$Resultaten = Get-AllBrowserExtensions -ExcludeSystem

    if ($Resultaten.Count -gt 0) {
        $Resultaten | Format-List
    } else {
        Write-Host "Geen (gebruikers-)extensies gevonden of mappen bestaan niet." -ForegroundColor Yellow
    }
} catch {
    Write-Host "FATALE FOUT in hoofdlus opgevangen: $($_.Exception.Message)" -ForegroundColor Red
    # Hier zou je ErrorHandler functie aangeroepen worden
}

# --- Uitvoering van het script ---
# Gebruik de switch -ExcludeSystem om de lijst op te schonen
[array]$Resultaten = Get-AllBrowserExtensions -ExcludeSystem
', N'', NULL, N'', N'', 0)


